import type { Transaction } from "dexie";
import type { Instant } from "@/domain/shared/time";
import type { JagaOnTableName } from "../table-catalogue";

/**
 * Closed storage-migration contracts (storage-backup-spec Sections 5.2–5.8).
 *
 * A registered migration is a reviewed application asset. Its transformation
 * is deterministic and side-effect free: it uses only the version-change
 * transaction and the values passed in `MigrationInputs`. Random identity
 * and the instant are generated by injected ports during preflight, never
 * inside the transformation; no network, AI, UI, notification, clock or
 * random access happens there.
 */

export type StorageMigrationDefinition = {
  migrationId: string;
  fromDexieVersion: number;
  toDexieVersion: number;
  fromLogicalSchemaVersion: number;
  toLogicalSchemaVersion: number;
  implementationVersion: string;
  expectedPreviousMigrationId?: string;
  affectedTables: JagaOnTableName[];
  changesPatientContent: boolean;
  requiresExplicitRecomputation: boolean;
};

export type MigrationInputs = {
  /** New random local dataset identity generated during preflight. */
  datasetIdentity: string;
  /** Preflight instant recorded as the migration's start and completion time. */
  at: Instant;
};

/** Test-only fault injection: throw after the named transformation step. */
export type MigrationFaultPoint = "BEFORE_TRANSFORM" | "AFTER_IDENTITY" | "AFTER_STATE" | "DURING_VERIFY";

export type MigrationContext = {
  transaction: Transaction;
  inputs: MigrationInputs;
  /** Re-validates every row through the closed registry inside the version change. */
  verifyAllRows(transaction: Transaction): Promise<void>;
  fault?: MigrationFaultPoint;
};

export type RegisteredStorageMigration = {
  definition: Readonly<StorageMigrationDefinition>;
  /** SHA-256 of the canonical JSON of `definition`, frozen at review time. */
  definitionSha256: string;
  transform(context: MigrationContext): Promise<void>;
};
